INSERT INTO warranties (brand_name, duration_months, distance_limit_km, conditions, source_id) SELECT 'Toyota', 36, 100000, 'Basic new-vehicle warranty; whichever limit comes first. Extended programs have separate conditions.', 'toyota_warranty' WHERE NOT EXISTS (SELECT 1 FROM warranties WHERE car_id IS NULL AND brand_name = 'Toyota' AND source_id = 'toyota_warranty');
